"""Version comparison from final NBT renders; no generated or retouched model imagery."""
from pathlib import Path
import csv,json,shutil,sys
from make_review import uri,esc,JS,LABEL
CASE=Path(__file__).resolve().parents[1];ROOT=CASE.parents[1]
OUT=ROOT/'deliverables/nanshan_cloud_v2';STEM='Nanshan_Cloud_HAF_V2'
Q={'se':'东南','sw':'西南','ne':'东北','nw':'西北'}

def main():
    OUT.mkdir(parents=True,exist_ok=True)
    run=CASE/'runs/V2_r01';prev=CASE/'review/previews/V2_r01'
    m=json.loads((run/'manifest.json').read_text());qa=json.loads((CASE/'validation/v2/acceptance.json').read_text());imp=json.loads((run/'import_pack/import_manifest.json').read_text())
    labels={**{q+'_'+mode:f'{name} 45° · '+('日间' if mode=='day' else '夜间') for q,name in Q.items() for mode in ['day','night']},**LABEL}
    views={k:{'src':uri(prev/(k+'.png')),'label':label} for k,label in labels.items()}
    comparisons={}
    compare_ids=['front','overview','hills','top']+[q+'_'+mode for q in Q for mode in ['day','night']]
    for k in compare_ids:
        source=CASE/'review/previews'/('V1_compare45' if k.split('_')[0] in Q else 'V1_r04')/(k+'.png')
        comparisons[k]={'before':uri(source),'after_key':k,'beforeLabel':'V1 / r04 · 保留原版','note':'固定相机、尺度、光照策略；V2 收小平台并改为上部三行等宽。四个斜角为模型坐标方向，地理北尚未核实。'}
    materials=(run/'materials.csv').read_text(encoding='utf-8-sig')
    data=dict(views=views,comparisons=comparisons,hash=m['sha256'],components=['hills.front','hills.right','hills.inner','tower.facade','base','roof','lighting.fixed','interior','export.views'],material_csv=materials)
    photos=[]
    for filename,title in [('user-001.png','你提供的正面参考'),('img-022.jpg','已有高分辨率正面夜景')]:
        p=CASE/'research/images'/filename
        body=f'<img data-zoom src="{uri(p, "image/png" if p.suffix==".png" else "image/jpeg")}" alt="{title}">' if p.exists() else '<p>图片未重复收入源码包；可查看交付报告或来源。</p>'
        photos.append(f'<article class="card"><h3>{title}</h3>{body}</article>')
    matrows=sorted(csv.DictReader(materials.splitlines()),key=lambda r:int(r['count']),reverse=True)
    table=''.join(f'<tr><td>{esc(r["block_id"].removeprefix("minecraft:"))}</td><td>{int(r["count"]):,}</td></tr>' for r in matrows[:12])
    dropdown=''.join(f'<option value="{k}">{esc(labels[k])}</option>' for k in compare_ids)
    quadrant=''.join(f'<article><h3>{name} 45°</h3><img class="quadImage" id="quad_{q}" alt="{name} 45 度模型视图"></article>' for q,name in Q.items())
    sections=[]
    def sec(id,title,body):sections.append(f'<section id="{id}"><h2>{title}</h2>{body}</section>')
    sec('result','01 / 露台收小，楼高保持',f'''<div class="three"><div class="metric"><span class="value">64 → 50 格</span>正面露台最大玻璃宽度</div><div class="metric"><span class="value">8 → 5 格</span>相对主塔玻璃面的外挑</div><div class="metric"><span class="value">235 格</span>最高塔体 · 沿用 V1</div></div><p>本轮按你的反馈集中调整露台：减少覆盖塔面的面积，缩短外挑，将“每层等量收窄”改成“上部三行等宽、下部逐级加宽”。四组平台的高度和主塔尺寸延续 V1，方便判断露台比例本身的影响。</p><p class="note">图像来自最终 NBT 的几何读回，未加载游戏资源包纹理；不是 Minecraft 游戏截图。尺寸是本轮可复核的建造参数，不是建筑测绘结果。</p>''')
    sec('compare','02 / V1 × V2 · 同视角对比',f'''<div class="toolbar"><label for="comparePart">选择比较位置</label><select id="comparePart">{dropdown}</select></div><div class="two compare"><article><h3 id="beforeLabel"></h3><img id="beforeImage" alt="V1 原版"></article><article><h3 id="afterLabel"></h3><img id="afterImage" alt="V2 修订版"></article></div><p id="compareNote"></p><p class="muted">保留 V1 原始建筑及其 13 张预览。V1 的新增四向相机图放在独立对照目录，由原 NBT 渲染；没有改写 V1。</p>''')
    sec('quadrants','03 / 四个 45° 全景 · 后续默认交付',f'''<div class="toolbar"><label for="quadMode">四面联动</label><select id="quadMode"><option value="day">日间</option><option value="night">夜间</option></select></div><div class="quad-grid">{quadrant}</div><p>每个方向有独立的 1800 × 2400 原图，点击可放大。四个方向共用中心、俯角和缩放；新旧版本也共用相机。未来导出默认展示东南、西南、东北、西北。</p><p class="note">当前“东 = +X、北 = −Z”仅用于模型坐标。实际建筑的地理朝向尚未核实，不能用这些标签推断现场朝向。</p>''')
    sec('gallery','04 / 21 张图 · 全景和局部', '<div id="viewButtons" class="thumbs"></div><div class="viewer"><img id="mainImage" alt="建筑模型"><div class="caption"><strong id="imageTitle"></strong><div id="imageNote" class="muted"></div></div></div>')
    sec('sources','05 / 参考判断与参数',f'''<div class="two photo-pair">{''.join(photos)}</div><p>继续使用已有研究图，并结合本轮提供的照片。采用上部近似等宽、下部逐级放宽的可见轮廓；这些行是模型中的幕墙段，不直接宣称是实测办公层。</p><p class="small">高分辨率图来自 <a href="https://betterfutureawards.com/LON20/project.asp?ID=20077" target="_blank" rel="noopener">既有灯光项目资料</a>（<a href="https://d39lxsrz40jt15.cloudfront.net/downloads/EDG2012/o_1eddtc97nlej18bb1f0jvrepsn10.jpg" target="_blank" rel="noopener">原始图片</a>）；此前已查看图片，奖项页面未完整取回。图片版权归原权利人。</p><table><tr><th>检查量</th><th>V1</th><th>V2</th></tr><tr><td>正面玻璃段宽度，由下到上</td><td>64 / 58 / 52 / 46 / 40 / 34 / 28</td><td>50 / 44 / 38 / 32 / 26 / 26 / 26</td></tr><tr><td>最宽玻璃段 / 72 格主塔跨度</td><td>88.9%</td><td>69.4%</td></tr><tr><td>正面、右面玻璃外挑</td><td>8 格</td><td>5 格</td></tr><tr><td>外侧压边</td><td>另伸出 1 格</td><td>另伸出 1 格</td></tr><tr><td>平台四组起始标高</td><td>14 / 66 / 118 / 170</td><td>保持；均相对地面</td></tr><tr><td>最高塔体 / 主塔正面跨度</td><td>235 / 72 格</td><td>保持</td></tr></table><p class="muted">正面取照片约束，右侧取斜视图近似，内侧平台仍为弱证据估算。没有新增 SU 文件，也没有完成摄影测量或自动图像分割。</p>''')
    sec('logic','06 / 这次修改到哪里','''<div class="three"><article class="card"><h3>独立露台轮廓</h3><p>params.json 为正面、右面、内侧各保存宽度序列和深度区间。生成器据此形成楼板和围护，不再只用统一线性缩进。</p></article><article class="card"><h3>灯带跟随构件</h3><p>固定暖色灯带改为读取平台真实边界；平台变窄时灯带同步缩短，避免旧灯位悬空。稳定房间种子、冷暖材料规则沿用。</p></article><article class="card"><h3>四面导出</h3><p>共享渲染入口自动补全四向日夜图，并限制每批相机数。原有正面、背面、俯视、近景和剖切继续保留。</p></article></div><p>当前更接近“直立塔体 + 局部阶梯平台”的层次。是否已经足够协调，仍需你的视觉判断。后部接口和第三塔比例继续标为待核实。</p>''')
    sec('validation','07 / 验证与边界',f'''<table><tr><th>类别</th><th>本轮结果</th></tr><tr><td>文件与状态</td><td>{m['non_air_blocks']:,} 个方块；NBT 独立读回一致</td></tr><tr><td>修订检查</td><td>{len(qa['checks'])} 项通过：实际玻璃宽度、灯带边界、空洞、四向相机和预览来源等</td></tr><tr><td>共享代码</td><td>33 项单元测试通过</td></tr><tr><td>历史保护</td><td>V1 基线记录的 39 个文件哈希保持一致</td></tr><tr><td>复现</td><td>新运行完整重跑得到相同 NBT 哈希</td></tr><tr><td>导出</td><td>Schem 回读一致；{imp['module_count']} 个分区逐坐标/状态拼合一致</td></tr><tr><td>视觉</td><td>已查看本轮模型；建筑还原度等待用户评价</td></tr><tr><td>游戏</td><td>Minecraft 导入、纹理、邻接更新、光照和全楼通行仍待测试</td></tr></table><p class="muted">技术检查不能给出写实度分数。页面交互采用离线 DOM 检查；本轮没有可用 Chromium，未声称完成浏览器布局或游戏内验证。</p>''')
    sec('materials','08 / 建筑文件与材料',f'''<div class="two"><article class="card"><h3>材料清单</h3><table><tr><th>材料 ID</th><th>数量</th></tr>{table}</table></article><article class="card"><h3>V2 可用文件</h3><p>{m['material_types']} 种材料，{m['state_types']} 种精确状态。玻璃片、铁栅栏、半砖等按实际方块计数。</p><p><button id="downloadMaterials">下载完整材料 CSV</button></p><p><a class="download" download="{STEM}.schem" href="{uri(run/'import_pack'/(STEM+'.schem'),'application/octet-stream')}">下载 V2 .schem</a></p><p>建筑包另含完整 NBT、分区、坐标表、导入说明和 21 张原始预览。完整 .schem 包含空气，建议先在空白场地试放。</p><p class="muted">完整包围盒为 140 × 244 × 140；格式目标沿用 V1。实际导入兼容性需在你的工具中确认。</p></article></div>''')
    sec('code','09 / 可回顾的修改记录','''<p>源码包保留 V1 参数、生成器、建筑与预览；本轮 V2 参数、最终输出、差分统计和验证记录另存。反馈项在 research/v2_feedback.json，轮廓修改在 src/build_case.py，四面规则在 hafusion/views.py 与 AGENTS.md。</p><p>这是建造规则与案例评估记录，不是已经训练完成的神经网络模型。后续可以只调整某一面的宽度和深度，不必重新设计整栋的构件分层。</p><pre>python3 tools/agent.py --case nanshan_cloud --run MY_NEW_RUN
python3 tools/render_building_case.py --case nanshan_cloud --run MY_NEW_RUN
python3 tools/package_building_case.py --case nanshan_cloud --run MY_NEW_RUN --name Nanshan_Cloud_Custom</pre>''')
    sec('feedback','10 / 下一轮反馈 · 落到构件','''<p>记录想保留或继续调整的部位，导出 JSON 即可带回项目。填写不会自动修改建筑。</p><form id="feedbackForm"><div class="feedback-grid"><div><label for="fbPart">构件</label><select id="fbPart"></select></div><div><label for="fbView">视图</label><select id="fbView"></select></div><div><label for="fbPriority">优先级</label><select id="fbPriority"><option value="high">形态与比例</option><option value="medium">细节与材质</option></select></div></div><p><label for="fbProblem">哪里不像 / 哪些值得保留</label><textarea id="fbProblem" required></textarea></p><p><label for="fbChange">希望怎样调整</label><textarea id="fbChange" required></textarea></p><p><label for="fbEvidence">参考链接（可选）</label><input id="fbEvidence" type="url"></p><button type="submit">保存此条</button> <button type="button" id="exportFeedback">导出反馈 JSON</button></form><p id="fbStatus"></p><p id="feedbackCount"></p><div id="feedbackList"></div>''')
    js=JS.replace("let view='overview'","let view='se_day'").replace('nanshan-cloud-v1-feedback','nanshan-cloud-v2-feedback').replace('Nanshan_Cloud_HAF_V1','Nanshan_Cloud_HAF_V2').replace('V1_r04','V2_r01').replace('V1 / r04 · 交付基线','V2 / r01 · 露台收窄').replace("view==='night'","view.endsWith('night')").replace("?'本轮原型':'交付基线'","?'V1 原版':'V2 修订版'")
    js=js.replace("$('afterImage').src=v.after","$('afterImage').src=D.views[v.after_key].src")
    js+='''\nfunction quads(){for(const q of ['se','sw','ne','nw']){const v=D.views[q+'_'+$('quadMode').value];const e=$('quad_'+q);e.src=v.src;e.alt=v.label;e.onclick=()=>zoom(v.src,v.label)}}$('quadMode').onchange=quads;quads();\n'''
    css=(CASE/'review/assets/style.css').read_text()+'''\n.quad-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.quad-grid img{width:100%;cursor:zoom-in}.quad-grid h3{font-size:16px}.compare img{width:100%;max-height:none}.photo-pair img{height:420px;object-fit:contain}.viewer img{max-height:900px}pre{overflow:auto;white-space:pre-wrap;background:#eaf0ef;padding:20px;border-radius:10px}select{max-width:100%}@media(max-width:1000px){.quad-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.compare{grid-template-columns:1fr}.photo-pair img{height:320px}}'''
    page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>南山云科技大厦 · V1 / V2 对照</title><style>'''+css+'''</style></head><body><header><small>HAIBARA’S ARCHITECT / HAF 0.2</small><h1>露台收窄后的<br>南山云科技大厦</h1><p>V1 × V2 · 保留楼高，修正平台比例<br>四个 45° 方向 · 同相机日夜对照</p></header><nav><a href="#compare">版本对比</a><a href="#quadrants">四个方向</a><a href="#gallery">全部大图</a><a href="#materials">材料与文件</a><a href="#feedback">反馈</a></nav><main>'''+''.join(sections)+'''</main><footer>HAF 0.2 / Nanshan Cloud V2_r01 · 原版 V1 保留 · 模型轴向未标定地理北</footer><dialog id="zoom"><div class="zoom-head"><strong id="zoomTitle"></strong><button id="zoomActual">适应 / 原始尺寸</button><button id="zoomClose">关闭</button></div><div class="zoom-scroll"><img id="zoomImg" alt="原始大图"></div></dialog><script id="data" type="application/json">'''+json.dumps(data,ensure_ascii=False).replace('</',r'<\/')+'''</script><script>'''+js+'''</script></body></html>'''
    dest=OUT/(STEM+'_Review.html');dest.write_text(page)
    shutil.copy2(prev/'overview.png',OUT/(STEM+'_Overview.png'))
    print(json.dumps({'file':str(dest),'bytes':dest.stat().st_size,'views':len(views),'comparisons':len(comparisons)},ensure_ascii=False))
if __name__=='__main__':main()
